using System.Net;
using System.Numerics;
using System.Text;
using Phoney.Generation;

namespace Phoney.Tests;

/// <summary>
/// Every scalar type Phoney knows (<see cref="ConventionRules.CategoryOf"/>) is generated by the reflection model. The source generator maps the same categories to
/// <c>ConventionValues</c> calls on its own (<c>ScalarCoverageTests</c> in the generator tests lists the same types), so a category added to one side fails a test.
/// </summary>
public sealed class ScalarCoverageTests
{
    /// <summary>One representative type per scalar category.</summary>
    public static readonly Type[] Scalars =
    [
        typeof(string), typeof(char), typeof(bool), typeof(byte), typeof(sbyte), typeof(short), typeof(ushort), typeof(int), typeof(uint), typeof(long), typeof(ulong),
        typeof(float), typeof(double), typeof(decimal), typeof(Guid), typeof(DateTime), typeof(DateTimeOffset), typeof(DateOnly), typeof(TimeOnly), typeof(TimeSpan),
        typeof(Uri), typeof(Half), typeof(Int128), typeof(UInt128), typeof(BigInteger), typeof(nint), typeof(nuint), typeof(Rune), typeof(IPAddress), typeof(Version),
        typeof(DayOfWeek),
    ];

    [Test]
    public void The_list_covers_every_scalar_category()
    {
        var categories = Scalars.Select(t => ConventionRules.CategoryOf(t.FullName!, t.IsEnum)).ToList();

        categories.ShouldNotContain(TypeCategory.Other);
        categories.Distinct().Count().ShouldBe(categories.Count, "one type per category");
        Enum.GetValues<TypeCategory>().Where(c => c != TypeCategory.Other).ShouldBe(categories, ignoreOrder: true);
    }

    [Test]
    public void The_reflection_model_produces_a_value_for_every_scalar_category()
    {
        foreach (var type in Scalars)
        {
            var values = Fake.Many(type, 40);
            values.Cast<object?>().Any(v => v is not null && !IsDefault(v)).ShouldBeTrue(type.Name);
        }
    }

    private static bool IsDefault(object value) => value.GetType().IsValueType && value.Equals(Activator.CreateInstance(value.GetType()));
}
